import {P,GEM_RAMPS} from './palette.js';
import {MATERIALS} from './materials.js';
import {gemIcon} from './expedition-map.js';
import {flowSprite,loadVillageArt} from './flow-village.js';
import {MINER_STEP_MS,MINER_CAP,FRAGMENT_CAP,GRAVEL_CAP,MINER_UPGRADES,minerYield,minerCapacity,minerEmpty,minerRare,minerTile,minerBlock,minerOffline,minerMultiplier,REFINE_RATIO,EXCHANGE_RATIO,EXCHANGE_FEE,minerKind,minerRate,minerUpgrade,settleMiner,setMinerEnabled,setMinerFocus,upgradeMiner,refineFragments,exchangeCrystals} from './miner.js';

const fmt=n=>new Intl.NumberFormat('pt-BR').format(n);
const hash=(x,y)=>{let n=Math.imul(x+1,374761393)^Math.imul(y+1,668265263);n=Math.imul(n^(n>>>13),1274126177);return (n^(n>>>16))>>>0;};
const blend=(a,b,t)=>a+(b-a)*t;
const smooth=t=>t*t*(3-2*t);
function box(c,x,y,w,h,color,r=8){c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
function gem(c,x,y,size,k){const [base,shade]=GEM_RAMPS[k];c.save();c.translate(x,y);c.fillStyle=base;c.strokeStyle=P.ink;c.lineWidth=2;c.beginPath();c.moveTo(0,-size);c.lineTo(size*.72,-size*.35);c.lineTo(size*.6,size*.65);c.lineTo(0,size);c.lineTo(-size*.6,size*.65);c.lineTo(-size*.72,-size*.35);c.closePath();c.fill();c.stroke();c.fillStyle=shade;c.beginPath();c.moveTo(0,0);c.lineTo(size*.72,-size*.35);c.lineTo(size*.6,size*.65);c.lineTo(0,size);c.closePath();c.fill();c.restore();}

export class MinerGame{
 constructor({state,music,onSave,onUpdate,open,soft,onSound,welcome}){Object.assign(this,{s:state,music,onSave,onUpdate,open,soft,onSound,welcome});this.tab='mine';this.from=0;this.to=1;this.amount=1;this.particles=[];this.popups=[];this.active=false;this.lastPaint=0;this.lastBeat=-1;this.lastStat=-1;this.previewUntil=0;this.visualDepth=0;this.machineX=350;loadVillageArt();}
 show(){if(this.s.run)return;const away=settleMiner(this.s,Date.now());this.active=true;this.lastPaint=0;this.lastBeat=-1;this.visualDepth=this.s.miner.steps;this.machineX=112+this.s.miner.col*68;this.open(`<section class="miner-layout"><div class="miner-theater"><canvas id="minerCanvas" width="700" height="580" role="img" aria-label="Broca pesada automática: cascalho, dinamite, frenesi e desvios"></canvas><div class="miner-scene-hud"><span id="minerDepth"></span><strong id="minerCombo"></strong></div><div class="miner-heat"><progress id="minerHeat" max="50" value="0" aria-label="Aquecimento para pulso sísmico"></progress><span id="minerHeatLabel"></span></div><div class="miner-scene-bottom"><span id="minerStatus"></span><div class="miner-play-controls"><button id="minerSound" class="secondary" aria-label="Ativar som da broca">♫</button><button id="minerToggle" class="primary"></button></div></div><div id="minerBurst" class="miner-burst" aria-live="polite"></div></div><aside class="miner-controls"><div class="miner-stone-wallet"><span>▰ CASCALHO</span><strong id="minerGravel">0</strong><small id="minerLevel"></small><small id="minerYield"></small></div><div class="miner-tabs" role="tablist" aria-label="Broca"><button data-miner-tab="mine" role="tab">BROCA</button><button data-miner-tab="exchange" role="tab">TROCAR</button>${this.s.miner.fragments.some(n=>n>0)?'<button data-miner-tab="refine" role="tab">RESERVA</button>':''}</div><div id="minerPanel"></div><details class="miner-jackpots"><summary>CRISTAIS ENCONTRADOS</summary><div class="miner-wallet">${MATERIALS.map((m,i)=>`<div style="--gem:${m.color}">${gemIcon(i)}<strong id="miner-count-${i}">0</strong><span>${m.name}</span></div>`).join('')}</div></details><p id="minerReceipt" role="status"></p></aside></section>`);
 this.canvas=document.getElementById('minerCanvas');this.ctx=this.canvas.getContext('2d');this.root=this.canvas.closest('.miner-layout');this.root.querySelectorAll('[data-miner-tab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.minerTab;this.panel();});document.getElementById('minerToggle').onclick=()=>{setMinerEnabled(this.s,!this.s.miner.enabled,Date.now());this.lastBeat=-1;this.commit();this.stats();};document.getElementById('minerSound').onclick=async()=>{await this.onSound();this.stats();};this.panel();this.stats();const welcome=this.welcome||away;if(welcome.gravel>0)this.receipt('AFK +'+fmt(welcome.gravel)+' CASCALHO');this.welcome=null;this.onSave();
 }
 commit(){this.onSave();this.onUpdate();}
 receipt(text){const el=document.getElementById('minerReceipt');if(!el)return;el.textContent=text;el.animate(this.soft()?[{opacity:.5},{opacity:1}]:[{transform:'scale(1.08)',color:P.yellow},{transform:'scale(1)',color:P.white}],{duration:500});}
 panel(){if(!this.active)return;const s=this.s,m=s.miner,cost=minerUpgrade(s);const host=document.getElementById('minerPanel');this.root.querySelectorAll('[data-miner-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.minerTab===this.tab));});
 if(this.tab==='mine'){
 host.innerHTML=`<div class="miner-upgrades">${Object.keys(MINER_UPGRADES).map(id=>{const u=minerUpgrade(s,id);return `<button data-upgrade="${id}" class="miner-push" title="${u.effect}" ${!u.ready||m.gravel<u.cost?'disabled':''}><span class="miner-up-icon">${u.icon}</span><span><b>${u.name} · ${u.level}</b><small>${u.effect}</small></span><strong>${u.ready?fmt(u.cost)+' ▰':'MÁX.'}</strong></button>`;}).join('')}</div><div class="miner-focus"><h3>JACKPOT</h3><div role="group" aria-label="Cristal prioritário"><button data-focus="-1" aria-pressed="${m.focus===-1}">TODOS</button>${MATERIALS.map((v,i)=>`<button data-focus="${i}" aria-label="Priorizar ${v.name}" aria-pressed="${m.focus===i}">${gemIcon(i)}</button>`).join('')}</div></div><details class="miner-rules"><summary>REGRAS</summary><p>Cascalho melhora só a broca. Cristais são raros.</p><p>50 blocos em sequência = pulso + prêmio. Mais profundidade e núcleo = prêmios maiores. Rocha densa esfria o combo.</p><p>TNT limpa 3×3; dinamite aprimorada limpa 5×5. Frenesi: velocidade ×4 por 5 segundos.</p><p>Offline: ${minerOffline(m)/3600000} h. Não dá moedas, estrelas, experiência ou passes.</p></details>`;
 host.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{setMinerFocus(s,Number(b.dataset.focus),Date.now());this.commit();this.panel();this.stats();});
 host.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const id=b.dataset.upgrade;if(upgradeMiner(s,Date.now(),id)){this.music.sfx('drillHit');this.receipt(MINER_UPGRADES[id].name+' MELHORADO!');this.commit();this.panel();this.stats();}});
 }else if(this.tab==='refine'){
 host.innerHTML=`<h3>FRAGMENTOS GUARDADOS</h3><p class="miner-rule">RESERVA ANTIGA · 2.000 → 1</p><div class="miner-refine-list">${MATERIALS.map((v,i)=>`<div style="--gem:${v.color}">${gemIcon(i)}<strong>${v.name}</strong><button data-refine="${i}" data-amount="1">+1</button><button data-refine="${i}" data-amount="all">TODOS</button></div>`).join('')}</div>`;
 host.querySelectorAll('[data-refine]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.refine),n=b.dataset.amount==='all'?Math.floor(m.fragments[i]/REFINE_RATIO):1;if(refineFragments(s,i,n)){this.music.reward();this.previewUntil=performance.now()+1400;this.burst('CRISTAL FORMADO!');this.receipt(`+${fmt(n)} ${MATERIALS[i].name.toUpperCase()}`);this.commit();this.stats();}});
 }else{
 const options=selected=>MATERIALS.map((v,i)=>`<option value="${i}" ${selected===i?'selected':''}>${v.name}</option>`).join('');
 host.innerHTML=`<h3>TROCAR CRISTAIS</h3><div class="miner-exchange"><label>ENTREGAR<select id="minerFrom">${options(this.from)}</select></label><span class="miner-arrow">→</span><label>RECEBER<select id="minerTo">${options(this.to)}</select></label></div><label class="miner-amount">QUANTOS RECEBER?<input id="minerAmount" type="number" min="1" max="10000" step="1" value="${this.amount}" inputmode="numeric"></label><p id="minerTradeCost" class="miner-rule"></p><button id="minerExchange" class="primary">TROCAR</button><small>CASCALHO NÃO ENTRA NA TROCA</small>`;
 const sync=()=>{this.from=Number(host.querySelector('#minerFrom').value);this.to=Number(host.querySelector('#minerTo').value);this.amount=Number(host.querySelector('#minerAmount').value);this.tradePreview();};for(const id of ['minerFrom','minerTo','minerAmount'])host.querySelector('#'+id).oninput=sync;
 host.querySelector('#minerExchange').onclick=()=>{if(exchangeCrystals(s,this.from,this.to,this.amount)){this.music.loot(this.to);this.receipt(`+${fmt(this.amount)} ${MATERIALS[this.to].name.toUpperCase()}`);this.commit();this.stats();}};
 }
 this.stats();
 }
 tradePreview(){const s=this.s,n=this.amount,ok=Number.isSafeInteger(n)&&n>0&&n<=10000&&this.from!==this.to&&s.materials[this.from]>=n*EXCHANGE_RATIO&&s.bank>=n*EXCHANGE_FEE;document.getElementById('minerTradeCost').textContent=!Number.isSafeInteger(n)||n<1||n>10000?'QUANTIDADE INVÁLIDA':this.from===this.to?'ESCOLHA OUTRA COR':`${fmt(n*EXCHANGE_RATIO)} ${MATERIALS[this.from].name.toUpperCase()} + ${fmt(n*EXCHANGE_FEE)} MOEDAS → ${fmt(n)} ${MATERIALS[this.to].name.toUpperCase()}`;document.getElementById('minerExchange').disabled=!ok;}
 stats(){if(!this.active)return;const m=this.s.miner;for(let i=0;i<4;i++)document.getElementById('miner-count-'+i).textContent=fmt(m.crystals[i]);
 document.getElementById('minerGravel').textContent=fmt(m.gravel);document.getElementById('minerLevel').textContent='BROCA NV. '+m.level+' · OFFLINE '+minerOffline(m)/3600000+' H';
 document.getElementById('minerDepth').textContent=fmt(m.steps*3)+' m';document.getElementById('minerCombo').textContent='×'+minerMultiplier(m);document.getElementById('minerCombo').classList.toggle('miner-hot',m.overdrive>0);document.getElementById('minerHeat').value=m.combo;document.getElementById('minerHeatLabel').textContent=m.combo+' / 50 · PULSO';document.getElementById('minerStatus').textContent=m.gravel>=minerCapacity(m)?'CASCALHO CHEIO':!m.enabled?'EM REPOUSO':m.overdrive>0?'FRENESI ×4':minerBlock(m).type==='dense'?'ROCHA DENSA':'AFK ATIVO';document.getElementById('minerToggle').textContent=m.enabled?'PAUSAR':'LIGAR';const audio=document.getElementById('minerSound');audio.setAttribute('aria-label',this.music.enabled?'Silenciar broca':'Ativar som da broca');audio.setAttribute('aria-pressed',String(this.music.enabled));
 document.getElementById('minerYield').textContent='PRÊMIO ×'+minerYield(this.s).toFixed(2);this.root.querySelectorAll('[data-upgrade]').forEach(b=>{const u=minerUpgrade(this.s,b.dataset.upgrade);b.disabled=!u.ready||m.gravel<u.cost;});
 if(this.tab==='refine')this.root.querySelectorAll('[data-refine]').forEach(b=>{const i=Number(b.dataset.refine),n=Math.floor(m.fragments[i]/REFINE_RATIO);b.disabled=b.dataset.amount==='all'?n<2:n<1;if(b.dataset.amount==='all')b.textContent='MAX +'+fmt(n);b.title=fmt(m.fragments[i])+' FRAGMENTOS GUARDADOS';});
 if(this.tab==='exchange')this.tradePreview();
 }
 burst(text){const el=document.getElementById('minerBurst');if(!el)return;el.textContent=text;this.burstAnimation?.cancel();this.burstAnimation=el.animate(this.soft()?[{opacity:0},{opacity:1,offset:.15},{opacity:1,offset:.7},{opacity:0}]:[{opacity:0,transform:'scale(.6) rotate(-4deg)'},{opacity:1,transform:'scale(1.18) rotate(-4deg)',offset:.18},{opacity:1,transform:'scale(1) rotate(-4deg)',offset:.65},{opacity:0,transform:'scale(1.05) rotate(-4deg)'}],{duration:1500});}
 earned(result){if(!this.active||document.hidden)return;for(const e of result.events.slice(-5)){
 this.impact(e.kind,e.type==='bomb'||e.pulse,e.gravel,e.crystal,e.crystalAmount);
 if(e.type==='titanium'){this.bumpAt=performance.now();this.bumpDir=e.to-e.from;this.music.sfx('drillDeflect');}
 else if(e.pulse){this.waveAt=performance.now();this.burst('PULSO SÍSMICO!');this.music.sfx('drillPulse');}
 else if(e.type==='bomb'){this.blastAt=performance.now();this.burst('DINAMITE!');this.music.sfx('drillBomb');}
 else if(e.type==='overdrive'){this.burst('FRENESI ×4');this.music.sfx('drillBoost');}
 else if(e.type==='dense')this.music.sfx('drillDense');else this.music.sfx('drillHit');
 if(e.crystal>=0){this.music.loot(e.crystal);this.receipt('+'+fmt(e.crystalAmount)+' '+MATERIALS[e.crystal].name.toUpperCase());}
 }this.stats();}
 impact(k,huge=false,amount=0,crystal=-1,crystalAmount=1){const now=performance.now(),p=this.machinePoint||{x:350,y:295},count=this.soft()?4:huge?48:12;for(let i=0;i<count;i++){const a=i/count*Math.PI*2,v=80+hash(i,this.s.miner.steps)%130;this.particles.push({x:p.x,y:p.y+22,vx:Math.cos(a)*v,vy:-140-Math.abs(Math.sin(a)*v),born:now,life:huge?1100:750,k:crystal>=0&&i%4===0?crystal:-1,size:4+i%7});}this.particles=this.particles.slice(-96);if(amount>0)this.popups.push({x:p.x,y:p.y-80,born:now,text:'+'+fmt(amount)+' ▰',k:-1});if(crystal>=0)this.popups.push({x:p.x,y:p.y-120,born:now,text:'+'+fmt(crystalAmount)+' '+MATERIALS[crystal].name.toUpperCase(),k:crystal});this.popups=this.popups.slice(-8);this.hitAt=now;}
 frame(now){if(!this.active||document.hidden||!this.canvas?.isConnected)return;if(now-this.lastPaint<1000/30)return;const dt=Math.min(.1,(now-(this.lastPaint||now))/1000);this.lastPaint=now;const m=this.s.miner,block=minerBlock(m),extra=m.enabled?Math.min(999,Math.max(0,Date.now()-m.lastAt))*(100+2*(m.level-1))*(m.overdrive>0?4:1):0,phase=m.steps+Math.min(.99,(m.carry+extra)/block.work);
 this.visualDepth+=Math.max(-dt*3,Math.min(dt*3,(phase-this.visualDepth)*dt*8));this.machineX+=Math.min(1,dt*9)*(112+m.col*68-this.machineX);
 const beat=Math.floor(now/500);if(m.enabled&&beat!==this.lastBeat){if(this.lastBeat>=0){this.music.sfx(block.type==='dense'&&m.overdrive===0?'drillDense':'drillHit');}this.lastBeat=beat;}
 if(now-this.lastStat>250){this.stats();this.lastStat=now;}this.draw(now,this.visualDepth);
 }
 draw(now,phase){const c=this.ctx,m=this.s.miner,soft=this.soft(),moving=m.enabled&&!soft,w=700,h=580,step=Math.floor(phase),u=phase-step,scroll=moving?u*58:0,biome=Math.floor(m.steps/50)%4,walls=[P.deepTeal,P.coal,P.aubergine,P.forest][biome],base=[P.gray,P.clay,P.plum,P.forest][biome],shade=[P.slate,P.wood,P.aubergine,P.deepTeal][biome];
 box(c,0,0,w,h,P.ink,0);c.save();const blast=Math.max(0,1-(now-(this.blastAt||0))/450);if(blast&&!soft)c.translate(Math.sin(now*.09)*blast*9,Math.cos(now*.12)*blast*6);box(c,18,0,664,h,walls,0);
 const cell=68,left=112,active=minerBlock(m);
 // 13 × 7 visible tiles, bounded cut masks, no retained infinite map.
 for(let row=-5;row<8;row++){const absolute=step+row+1;if(absolute<1)continue;const y=290+row*58-scroll;for(let col=0;col<7;col++){const n=hash(col,absolute+m.seed),x=left+col*cell,type=minerTile(m,absolute,col);let cut=minerEmpty(m,absolute,col);
 if(cut)continue;
 const direct=absolute===m.steps+1&&col===m.col;
 const color=type==='bomb'?P.red:type==='overdrive'?P.orange:type==='titanium'?P.steel:type==='dense'?P.slate:base,shadow=type==='bomb'?P.maroon:type==='overdrive'?P.rust:type==='titanium'?P.slate:type==='dense'?P.ink:shade;
 this.cube(c,x,y,58,46,color,shadow);
 if(type==='bomb'){box(c,x-19,y-12,38,15,P.sand,3);c.fillStyle=P.ink;c.font='900 12px sans-serif';c.textAlign='center';c.fillText('TNT',x,y);}
 else if(type==='overdrive'){c.strokeStyle=P.yellow;c.lineWidth=6;c.beginPath();c.moveTo(x+5,y-15);c.lineTo(x-6,y);c.lineTo(x+6,y);c.lineTo(x-4,y+13);c.stroke();}
 else if(type==='titanium'){c.strokeStyle=P.ink;c.lineWidth=4;c.beginPath();c.moveTo(x-13,y-8);c.lineTo(x+12,y+7);c.moveTo(x+12,y-8);c.lineTo(x-13,y+7);c.stroke();}
 else if(direct?minerRare(m,absolute):n%100<2){gem(c,x,y,15,minerKind(m,absolute));}
 else if(type==='dense'){box(c,x-18,y-6,36,8,P.gray,3);box(c,x-12,y+6,24,7,P.gray,3);}
 if(direct&&m.carry/active.work>.3){c.strokeStyle=P.ink;c.lineWidth=3;c.beginPath();c.moveTo(x-9,y-10);c.lineTo(x+4,y);c.lineTo(x-3,y+12);c.stroke();}
 }}
 const x=this.machineX,bounce=moving?Math.max(0,Math.sin(now/(m.overdrive>0?55:160)))*10:0,bump=soft?0:Math.max(0,1-(now-(this.bumpAt||0))/500),hot=m.overdrive>0;
 this.machinePoint={x,y:295};box(c,x-63,295,126,19,P.ink,12);c.save();c.translate(x+(this.bumpDir||0)*bump*18,289-bounce);if(moving)c.rotate(Math.sin(now/100)*.018);flowSprite(c,'miningMachine',0,27,155,hot);
 if(hot){box(c,-43,-62,46,15,P.orange,5);box(c,-40,-59,16,9,P.red,3);c.strokeStyle=P.orange;c.lineWidth=6;c.beginPath();c.ellipse(0,24,77,22,0,0,Math.PI*2);c.stroke();}
 if(m.side>0){this.cube(c,-74,15,26,30,P.steel,P.slate);if(m.side>1)this.cube(c,74,15,26,30,P.steel,P.slate);}c.restore();
 const wave=Math.max(0,Math.min(1,(now-(this.waveAt||-9999))/800));if(wave>0&&wave<1){c.strokeStyle=P.cyan;c.lineWidth=soft?4:16*(1-wave);c.beginPath();c.ellipse(x,310,30+wave*580,10+wave*300,0,0,Math.PI*2);c.stroke();}
 this.particles=this.particles.filter(p=>now-p.born<p.life);for(const p of this.particles){const t=(now-p.born)/1000,q=t*1000/p.life;c.save();c.globalAlpha=Math.min(1,(1-q)*4);const px=p.x+p.vx*t,py=p.y+p.vy*t+560*t*t;this.cube(c,px,py,p.size*2,p.size*1.5,p.k<0?base:GEM_RAMPS[p.k][0],p.k<0?shade:GEM_RAMPS[p.k][1]);c.restore();}
 this.popups=this.popups.filter(p=>now-p.born<1400);for(const p of this.popups){const q=(now-p.born)/1400;c.save();c.globalAlpha=Math.min(1,(1-q)*3);c.font='900 '+(p.k<0?28:33)+'px Bungee, sans-serif';c.textAlign='center';c.lineWidth=6;c.strokeStyle=P.ink;c.strokeText(p.text,p.x,p.y-q*55);c.fillStyle=p.k<0?P.sand:GEM_RAMPS[p.k][0];c.fillText(p.text,p.x,p.y-q*55);c.restore();}
 for(let y=-24;y<h;y+=58){box(c,42,y-scroll,28,48,P.wood,6);box(c,630,y-scroll,28,48,P.wood,6);box(c,45,y-scroll+3,9,42,P.clay,3);box(c,633,y-scroll+3,9,42,P.clay,3);}c.restore();
 }
 cube(c,x,y,w,h,color,shade){box(c,x-w/2-2,y-h/2-2,w+4,h+14,P.ink,Math.min(8,w/4));box(c,x-w/2,y-h/2,w,h+10,shade,Math.min(7,w/4));box(c,x-w/2,y-h/2,w,h-3,color,Math.min(7,w/4));c.fillStyle=shade;c.beginPath();c.moveTo(x+w*.25,y-h/2+2);c.lineTo(x+w/2,y-h/2+7);c.lineTo(x+w/2,y+h/2);c.lineTo(x+w*.25,y+h/2+7);c.closePath();c.fill();}
 leave(){this.active=false;this.particles=[];this.popups=[];this.burstAnimation?.cancel();this.canvas=null;this.ctx=null;this.onSave();this.onUpdate();}
}
